from rest_framework import serializers
from .models import Book


class BookSerializer(serializers.ModelSerializer):
    class Meta:
        model = Book
        fields = ["id", "title", "author", "isbn", "price", "created_at"]
        read_only_fields = ["id", "created_at"]
        extra_kwargs = {
            "title": {"error_messages": {"blank": "عنوان نمی‌تواند خالی باشد."}},
            "isbn": {"error_messages": {"unique": "این ISBN قبلاً ثبت شده است."}},
        }

    def validate_title(self, value):
        value = value.strip()
        if len(value) < 3:
            raise serializers.ValidationError("عنوان باید حداقل ۳ کاراکتر باشد.")
        return value

    def validate_isbn(self, value):
        clean = value.replace("-", "").strip()
        if not clean.isdigit():
            raise serializers.ValidationError("ISBN فقط می‌تواند رقم داشته باشد.")
        if len(clean) not in (10, 13):
            raise serializers.ValidationError("ISBN باید ۱۰ یا ۱۳ رقم باشد.")
        return clean

    def validate_price(self, value):
        if value <= 0:
            raise serializers.ValidationError("قیمت باید بزرگ‌تر از صفر باشد.")
        return value

from rest_framework import serializers
from .models import Book, Author


class AuthorSerializer(serializers.ModelSerializer):
    books_count = serializers.IntegerField(source="books.count", read_only=True)

    class Meta:
        model = Author
        fields = ["id", "full_name", "bio", "birth_date", "books_count"]


class BookReadSerializer(serializers.ModelSerializer):
    author = AuthorSerializer(read_only=True)

    class Meta:
        model = Book
        fields = ["id", "title", "author", "isbn", "price", "created_at"]


class BookWriteSerializer(serializers.ModelSerializer):
    class Meta:
        model = Book
        fields = ["id", "title", "author", "isbn", "price"]
        read_only_fields = ["id"]

    def validate_isbn(self, value):
        if not value.isdigit() or len(value) not in (10, 13):
            raise serializers.ValidationError("ISBN نامعتبر.")
        return value

    def validate_price(self, value):
        if value <= 0:
            raise serializers.ValidationError("قیمت باید مثبت باشد.")
        return value

from rest_framework import viewsets
from .models import Book, Author
from .serializers import AuthorSerializer, BookReadSerializer, BookWriteSerializer


class BookViewSet(viewsets.ModelViewSet):
    queryset = Book.objects.select_related("author").order_by("-created_at")

    def get_serializer_class(self):
        if self.action in ("create", "update", "partial_update"):
            return BookWriteSerializer
        return BookReadSerializer


class AuthorViewSet(viewsets.ReadOnlyModelViewSet):
    queryset = Author.objects.prefetch_related("books")
    serializer_class = AuthorSerializer
